// crate_macros.rs - Macros for loading external crates
// Generated by step4_bootstrap - Crate Integration System

pub use crate::crate_loader::*;

#[macro_export]
macro_rules! mkcrate {
    ($name:expr) => {{
        let source = load_crate_source($name).unwrap_or_default();
        let declarations = extract_declarations(&source);
        let names = extract_names(&declarations);
        
        CrateInfo {
            name: $name.to_string(),
            path: format!("../../{}", $name),
            declarations,
            names,
        }
    }};
}

#[macro_export]
macro_rules! mkdeps {
    ([$($crate_name:expr),*]) => {{
        let mut crates = Vec::new();
        $(
            let crate_info = mkcrate!($crate_name);
            crates.push(crate_info);
        )*
        crates
    }};
}

#[macro_export]
macro_rules! mkbootstrap_deps {
    () => {{
        // Start with essential crates for bootstrap
        mkdeps!(["anyhow", "serde", "serde_json", "toml"])
    }};
}
